product:
query Product($id: ID!, $isDraft: String, $variationId: ID, $src: String) {
  product(id: $id) {
    content(isDraft: $isDraft) {
      ...ProductContentFields
      __typename
    }
    id
    name
    description
    primaryCategoryId
    brand
    promotion {
      ...promoFields
      __typename
    }
    productStory {
      longDescription
      careInstructions
      __typename
    }
    price
    image {
      href
      alt
      __typename
    }
    brand
    orderable
    badge
    look(id: $variationId) {
      id
      image {
        href
        alt
        __typename
      }
      products {
        id
        __typename
      }
      __typename
    }
    score {
      rating
      amount
      __typename
    }
    ...sizes
    category {
      ...category
      parentCategory {
        ...category
        parentCategory {
          ...category
          parentCategory {
            ...category
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    variations {
      variantId
      specialMessage
      ean
      validUntil
      ...styles
      id
      badge
      salePrice
      price
      colorValue
      colorName
      preview
      sizes {
        id
        label
        orderable
        productId
        __typename
      }
      images {
        alt
        href
        __typename
      }
      materialComposition
      displayOutOfStock {
        soldout
        comingsoon
        backsoon
        presale
        displayValue
        validTo
        __typename
      }
      orderable
      manufacturerInfo {
        manufacturerAddress {
          label
          content
          __typename
        }
        countryOfOrigin {
          label
          content
          __typename
        }
        __typename
      }
      __typename
    }
    userGeneratedContentForWeb {
      source
      pixleeCdnPhotos {
        squareMediumUrl
        __typename
      }
      altText
      __typename
    }
    __typename
  }
}

